<script setup lang="ts">
import { ref } from 'vue';
import { api } from '../api';
import { type Row } from '../../shared/domain';
import { useWeather, weatherText, weatherSymbol, defaultCity, hometownCity } from '../../shared/weather';
const { city, weather, cities, search, error, loading, searching, current, days, load, find } = useWeather(api);
const choosing = ref(false), locating = ref(false);
function choose(row: Row) { choosing.value = false;load(row); }
function locate() {
  if (!navigator.geolocation || !window.isSecureContext) { error.value = '当前浏览器不支持定位，请使用HTTPS访问或手动选择城市。';return; }
  locating.value = true;error.value = '';
  navigator.geolocation.getCurrentPosition(position => { locating.value = false;choose({ name: '当前位置', latitude: position.coords.latitude, longitude: position.coords.longitude }); }, failure => { locating.value = false;error.value = failure.code === 1 ? '未获得定位授权，你仍可以手动选择城市。' : '暂时无法获取位置，请稍后重试或手动选城。'; }, { enableHighAccuracy: false, timeout: 10000, maximumAge: 600000 });
}
</script>
<template><section class="weather-card" aria-label="所在地天气"><header><span class="weather-eyebrow">出门前，看一眼天气</span><button @click="choosing = !choosing">⌖ {{ city.name }} <span>⌄</span></button></header><div v-if="loading" class="weather-loading">正在看看{{ city.name }}的天气…</div><template v-else-if="weather"><div class="weather-now"><div><strong>{{ Math.round(current.temperature_2m) }}<sup>°</sup></strong><p>{{ weatherText(current.weather_code) }} · 体感 {{ Math.round(current.apparent_temperature) }}°</p></div><span class="weather-symbol">{{ weatherSymbol(current.weather_code, !!current.is_day) }}</span></div><p class="weather-tip">{{ days[0]?.rain >= 50 ? '今天可能有雨，出门记得带把伞。' : current.temperature_2m < 15 ? '早晚添件衣，和老乡相聚也要照顾好自己。' : '带着好心情，去赴一场老乡的约。' }}</p><div class="weather-days"><div v-for="day in days" :key="day.date"><span>{{ day.label }}</span><i>{{ weatherSymbol(day.code) }}</i><b>{{ Math.round(day.low) }}° <small>/ {{ Math.round(day.high) }}°</small></b></div></div><footer><span>湿度 {{ current.relative_humidity_2m }}% · 风速 {{ current.wind_speed_10m }} km/h</span><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo ↗</a></footer><small class="weather-updated">{{ current.time?.replace('T', ' ') }} · 北京时间</small></template><div v-if="error" class="weather-error" role="status">{{ error }}<button :disabled="loading" @click="load()">重新获取</button></div><div v-if="choosing" class="weather-location"><h3>把天气，切到你身边</h3><div class="weather-shortcuts"><button @click="choose(defaultCity)">苏州</button><button @click="choose(hometownCity)">沭阳</button><button :disabled="locating" @click="locate">{{ locating ? '定位中…' : '使用我的位置' }}</button></div><p>仅用于天气查询，不写入会员资料。定位需要你的授权。</p><form @submit.prevent="find"><input v-model="search" aria-label="搜索天气城市" placeholder="输入城市名或拼音" maxlength="40"><button :disabled="searching">搜索</button></form><button v-for="row in cities" :key="row.id" class="city-result" @click="choose(row)">{{ row.name }}<small>{{ row.admin1 }} · {{ row.country }}</small></button></div></section></template>
<style scoped>
