x;margin-bottom:15px}.weather-shortcuts{display:flex;gap:7px;flex-wrap:wrap}.weather-shortcuts button{background:#f0e9da;font-size:11px;padding:8px 10px;border-radius:7px}.weather-location p{font-size:10px;color:#8b8579;margin:15px 0;line-height:1.8}.weather-location form{display:flex;border:1px solid #e0d8c7;border-radius:8px;padding:8px;gap:8px}.weather-location input{width:100%;min-width:0;border:0;outline:0;background:transparent;font-size:12px}.weather-location form button{white-space:nowrap;font-size:12px;color:#816641}.city-result{width:100%;text-align:left;display:block;padding:11px 0;border-bottom:1px solid #eee8dc;font-size:13px}.city-result small{display:block;font-size:10px;color:#9a8f7c;margin-top:5px}@media(max-width:700px){.weather-card{padding:22px;border-radius:20px}.weather-now{margin:18px 0 12px}.weather-now strong{font-size:62px}.weather-symbol{font-size:62px}.weather-tip{min-height:0}.weather-card footer{font-size:10px}.weather-updated{font-size:10px}}
</style>
